<?php
require_once __DIR__.'/includes/auth.php';require_role('Administrator');$from=page_param('from',date('Y-m-01',strtotime('-11 months')));$to=page_param('to',date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01',strtotime('-11 months'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');
if(isset($_GET['export'])){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="dams-report-'.$from.'-to-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Asset ID','Title','Filename','Category','Type','Size bytes','Uploader','Uploads date','Downloads']);$stmt=db()->prepare('SELECT a.asset_code,a.title,a.original_filename,c.name category,a.file_extension,a.file_size,u.name uploader,a.created_at,a.download_count FROM assets a LEFT JOIN categories c ON c.id=a.category_id JOIN users u ON u.id=a.uploaded_by WHERE a.deleted_at IS NULL AND DATE(a.created_at) BETWEEN ? AND ? ORDER BY a.created_at');$stmt->execute([$from,$to]);foreach($stmt as $row)fputcsv($out,$row);fclose($out);exit;}
$up=db()->prepare("SELECT DATE_FORMAT(created_at,'%Y-%m') label,COUNT(*) value FROM assets WHERE deleted_at IS NULL AND DATE(created_at) BETWEEN ? AND ? GROUP BY label ORDER BY label");$up->execute([$from,$to]);$uploads=$up->fetchAll();$dl=db()->prepare("SELECT DATE_FORMAT(downloaded_at,'%Y-%m') label,COUNT(*) value FROM downloads WHERE DATE(downloaded_at) BETWEEN ? AND ? GROUP BY label ORDER BY label");$dl->execute([$from,$to]);$downloads=$dl->fetchAll();$cat=db()->prepare("SELECT COALESCE(c.name,'Uncategorized') label,COUNT(*) value FROM assets a LEFT JOIN categories c ON c.id=a.category_id WHERE a.deleted_at IS NULL AND DATE(a.created_at) BETWEEN ? AND ? GROUP BY c.id,c.name ORDER BY value DESC");$cat->execute([$from,$to]);$categories=$cat->fetchAll();$types=db()->prepare("SELECT UPPER(file_extension) label,COUNT(*) value,SUM(file_size) bytes FROM assets WHERE deleted_at IS NULL AND DATE(created_at) BETWEEN ? AND ? GROUP BY file_extension ORDER BY value DESC");$types->execute([$from,$to]);$fileTypes=$types->fetchAll();$most=db()->query("SELECT id,title,original_filename,download_count,file_size FROM assets WHERE deleted_at IS NULL ORDER BY download_count DESC LIMIT 10")->fetchAll();$active=db()->query("SELECT u.name,u.email,COUNT(a.id) uploads,COALESCE(SUM(a.file_size),0) bytes FROM users u LEFT JOIN assets a ON a.uploaded_by=u.id AND a.deleted_at IS NULL GROUP BY u.id ORDER BY uploads DESC LIMIT 10")->fetchAll();$storage=db()->query("SELECT CASE WHEN file_extension IN ('jpg','jpeg','png','gif','webp','svg') THEN 'Images' WHEN file_extension IN ('mp4','webm') THEN 'Videos' WHEN file_extension IN ('mp3','wav') THEN 'Audio' WHEN file_extension='zip' THEN 'Archives' ELSE 'Documents' END label,SUM(file_size) value FROM assets WHERE deleted_at IS NULL GROUP BY label")->fetchAll();$pageTitle='Reports';$pageSubtitle='Analyze uploads, downloads, activity and storage';$pageActions='<a class="btn btn-outline-success" href="?'.e(http_build_query(['from'=>$from,'to'=>$to,'export'=>1])).'"><i class="bi bi-file-earmark-spreadsheet me-1"></i>Export CSV</a>';require __DIR__.'/includes/header.php';?>
<div class="card mb-4"><div class="card-body"><form class="row g-2 align-items-end"><div class="col-md-4"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-4"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-4"><button class="btn btn-primary w-100">Update report</button></div></form></div></div><div class="row g-4 mb-4"><div class="col-lg-8"><div class="card"><div class="card-header bg-white py-3"><h2 class="h6 mb-0">Uploads and downloads by month</h2></div><div class="card-body"><div class="chart-wrap"><canvas id="monthly"></canvas></div></div></div></div><div class="col-lg-4"><div class="card"><div class="card-header bg-white py-3"><h2 class="h6 mb-0">Storage by asset group</h2></div><div class="card-body"><div class="chart-wrap"><canvas id="storage"></canvas></div></div></div></div></div><div class="row g-4"><div class="col-xl-6"><div class="card"><div class="card-header bg-white py-3"><h2 class="h6 mb-0">Most downloaded assets</h2></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Asset</th><th>Size</th><th>Downloads</th></tr></thead><tbody><?php foreach($most as $a):?><tr><td><a href="<?=e(url('asset-details.php?id='.$a['id']))?>" class="text-decoration-none"><?=e($a['title'])?></a><small class="d-block text-muted"><?=e($a['original_filename'])?></small></td><td><?=e(human_file_size((int)$a['file_size']))?></td><td><?=number_format((int)$a['download_count'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-xl-6"><div class="card"><div class="card-header bg-white py-3"><h2 class="h6 mb-0">Most active uploaders</h2></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>User</th><th>Assets</th><th>Storage</th></tr></thead><tbody><?php foreach($active as $row):?><tr><td><?=e($row['name'])?><small class="d-block text-muted"><?=e($row['email'])?></small></td><td><?=$row['uploads']?></td><td><?=e(human_file_size((int)$row['bytes']))?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<div class="row g-4 mt-1"><div class="col-lg-6"><div class="card h-100"><div class="card-header bg-white py-3"><h2 class="h6 mb-0">Assets by category</h2></div><div class="card-body"><div class="chart-wrap"><canvas id="categoryReport"></canvas></div></div></div></div><div class="col-lg-6"><div class="card h-100"><div class="card-header bg-white py-3"><h2 class="h6 mb-0">Assets by file type</h2></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Type</th><th>Files</th><th>Storage</th></tr></thead><tbody><?php foreach($fileTypes as $row):?><tr><td><span class="badge text-bg-light"><?=e($row['label'])?></span></td><td><?=number_format((int)$row['value'])?></td><td><?=e(human_file_size((int)$row['bytes']))?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php $monthly=array_values(array_unique(array_merge(array_column($uploads,'label'),array_column($downloads,'label'))));sort($monthly);$uMap=array_column($uploads,'value','label');$dMap=array_column($downloads,'value','label');$uVals=array_map(fn($m)=>(int)($uMap[$m]??0),$monthly);$dVals=array_map(fn($m)=>(int)($dMap[$m]??0),$monthly);$extraScripts='<script>new Chart(monthly,{type:"bar",data:{labels:'.json_encode($monthly).',datasets:[{label:"Uploads",data:'.json_encode($uVals).',backgroundColor:"#5b5bd6"},{label:"Downloads",data:'.json_encode($dVals).',backgroundColor:"#10b981"}]},options:{maintainAspectRatio:false,scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});new Chart(storage,{type:"doughnut",data:{labels:'.json_encode(array_column($storage,'label')).',datasets:[{data:'.json_encode(array_map('intval',array_column($storage,'value'))).',backgroundColor:["#5b5bd6","#06b6d4","#10b981","#f59e0b","#ef4444"]}]},options:{maintainAspectRatio:false,plugins:{legend:{position:"bottom"}}}});new Chart(categoryReport,{type:"bar",data:{labels:'.json_encode(array_column($categories,'label')).',datasets:[{label:"Assets",data:'.json_encode(array_map('intval',array_column($categories,'value'))).',backgroundColor:"#5b5bd6"}]},options:{maintainAspectRatio:false,indexAxis:"y",plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,ticks:{precision:0}}}}});</script>';require __DIR__.'/includes/footer.php';?>
